files.content:
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: Arial, sans-serif;
  background: linear-gradient(135deg, #ff9a9e, #a18cd1);
}

.card {
  background: white;
  width: 320px;
  padding: 30px;
  border-radius: 20px;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.photo {
  width: 120px;
  height: 120px;
  margin: 0 auto;
  border-radius: 50%;
  background: linear-gradient(135deg, #fbc2eb, #a6c1ee);
  border: 5px solid #a18cd1;
  font-size: 64px;
  line-height: 120px;
  cursor: pointer;
}

h1 {
  color: #6a4c93;
}

.intro {
  color: #555;
}

h2 {
  color: #ff6f91;
  font-size: 20px;
}

.likes {
  list-style: none;
  padding: 0;
}

.likes li {
  background: #f3eaff;
  margin: 6px 0;
  padding: 8px;
  border-radius: 10px;
}

button {
  margin-top: 15px;
  padding: 10px 20px;
  border: none;
  border-radius: 20px;
  background: #6a4c93;
  color: white;
  font-size: 16px;
  cursor: pointer;
}

button:hover {
  background: #ff6f91;
}

.fact {
  min-height: 20px;
  color: #6a4c93;
  font-style: italic;
}

const photo = document.getElementById("photo");
const factButton = document.getElementById("fact-button");
const fact = document.getElementById("fact");

const faces = ["🙂", "😎", "🤪", "😄", "🥳"];
let faceNumber = 0;

const facts = [
  "I can eat a whole pizza by myself.",
  "My favourite colour is purple.",
  "I once scored a goal from the halfway line.",
  "I have watched my favourite film ten times.",
  "I want a dog called Biscuit."
];

photo.addEventListener("click", function () {
  faceNumber = faceNumber + 1;
  if (faceNumber >= faces.length) {
    faceNumber = 0;
  }
  photo.textContent = faces[faceNumber];
});

factButton.addEventListener("click", function () {
  const randomNumber = Math.floor(Math.random() * facts.length);
  fact.textContent = facts[randomNumber];
});

